<?php require_once __DIR__.'/lib/auth.php';startAppSession();if(currentUser()){header('Location: index.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){$s=db()->prepare('SELECT * FROM users WHERE email=? LIMIT 1');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location: index.php');exit;}$error='Invalid email or password.';}$mode='login';require __DIR__.'/views/auth.php';
